from __future__ import annotations

from typing import Any


DISCOUNTS = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
    "BULK5": 0.05,
}


def subtotal_cents(items: list[dict[str, Any]]) -> int:
    total = 0
    for item in items:
        total += int(item.get("unit_price_cents", 0)) * int(item.get("quantity", 0))
    return total


def discount_cents(subtotal: int, discount_code: str) -> int:
    code = discount_code.strip().upper()
    if not code:
        return 0
    pct = DISCOUNTS.get(code, 0.0)
    if pct <= 0:
        return 0
    if code == "SAVE20" and subtotal < 10_000:
        return 0
    return int(round(subtotal * pct))


def tax_cents(subtotal_after_discount: int, currency: str) -> int:
    cur = currency.strip().upper()
    if cur in {"USD", "AUD"}:
        pct = 0.10
    elif cur in {"EUR", "GBP"}:
        pct = 0.20
    else:
        pct = 0.10
    return int(round(subtotal_after_discount * pct))


def total_cents(subtotal: int, discount: int, tax: int) -> int:
    return subtotal - discount + tax


def compute_pricing(items: list[dict[str, Any]], currency: str, discount_code: str) -> dict[str, int]:
    sub = subtotal_cents(items)
    dis = discount_cents(sub, discount_code)
    taxed_base = sub - dis
    tax = tax_cents(taxed_base, currency)
    total = total_cents(sub, dis, tax)
    return {
        "subtotal_cents": sub,
        "discount_cents": dis,
        "tax_cents": tax,
        "total_cents": total,
    }


def explain_pricing(pricing: dict[str, int]) -> str:
    return (
        f"subtotal={pricing['subtotal_cents']} "
        f"discount={pricing['discount_cents']} "
        f"tax={pricing['tax_cents']} "
        f"total={pricing['total_cents']}"
    )

