from dataclasses import dataclass, field
from typing import Any


@dataclass(frozen=True)
class LineItem:
    sku: str
    unit_price_cents: int
    quantity: int

    def validate(self) -> None:
        if not self.sku.strip():
            raise ValueError("sku required")
        if self.unit_price_cents < 0:
            raise ValueError("unit_price_cents must be >= 0")
        if self.quantity <= 0:
            raise ValueError("quantity must be > 0")

    def subtotal(self) -> int:
        return self.unit_price_cents * self.quantity


@dataclass(frozen=True)
class OrderDraft:
    order_id: str
    user_id: str
    items: list[LineItem]
    currency: str = "USD"
    tags: list[str] = field(default_factory=list)

    def validate(self) -> None:
        if not self.order_id.strip():
            raise ValueError("order_id required")
        if not self.user_id.strip():
            raise ValueError("user_id required")
        if not self.items:
            raise ValueError("items required")
        if len(self.currency.strip()) != 3:
            raise ValueError("currency must be 3 letters")
        for item in self.items:
            item.validate()

    def subtotal_cents(self) -> int:
        return sum(item.subtotal() for item in self.items)


@dataclass(frozen=True)
class ProcessedOrder:
    order_id: str
    user_id: str
    subtotal_cents: int
    discount_cents: int
    tax_cents: int
    total_cents: int
    status: str
    meta: dict[str, Any]


def line_item_from_payload(payload: dict[str, Any]) -> LineItem:
    item = LineItem(
        sku=str(payload.get("sku", "")).strip(),
        unit_price_cents=int(payload.get("unit_price_cents", 0)),
        quantity=int(payload.get("quantity", 0)),
    )
    item.validate()
    return item


def order_draft_from_payload(payload: dict[str, Any]) -> OrderDraft:
    items_raw = payload.get("items", [])
    if not isinstance(items_raw, list):
        raise ValueError("items must be a list")
    items = [line_item_from_payload(item) for item in items_raw]
    draft = OrderDraft(
        order_id=str(payload.get("order_id", "")).strip(),
        user_id=str(payload.get("user_id", "")).strip(),
        items=items,
        currency=str(payload.get("currency", "USD")).strip().upper(),
        tags=[str(tag).strip() for tag in payload.get("tags", []) if str(tag).strip()],
    )
    draft.validate()
    return draft

