from __future__ import annotations

from threading import Lock


class Metrics:
    def __init__(self) -> None:
        self._lock = Lock()
        self._values: dict[str, int] = {}

    def incr(self, key: str, amount: int = 1) -> None:
        metric = key.strip()
        if not metric:
            return
        with self._lock:
            self._values[metric] = self._values.get(metric, 0) + amount

    def get(self, key: str) -> int:
        metric = key.strip()
        if not metric:
            return 0
        with self._lock:
            return self._values.get(metric, 0)

    def snapshot(self) -> dict[str, int]:
        with self._lock:
            return dict(self._values)

    def reset(self) -> None:
        with self._lock:
            self._values.clear()

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._values.keys())

    def total(self) -> int:
        with self._lock:
            return sum(self._values.values())

    def top(self, limit: int = 5) -> list[tuple[str, int]]:
        pairs = sorted(self.snapshot().items(), key=lambda item: item[1], reverse=True)
        return pairs[: max(0, int(limit))]

    def has(self, key: str) -> bool:
        return self.get(key) > 0

    def clear_key(self, key: str) -> bool:
        metric = key.strip()
        if not metric:
            return False
        with self._lock:
            if metric in self._values:
                del self._values[metric]
                return True
        return False

    def export_lines(self) -> list[str]:
        snap = self.snapshot()
        return [f"{k}={v}" for k, v in sorted(snap.items())]

    def percentile_like(self, ratio: float) -> int:
        values = sorted(self.snapshot().values())
        if not values:
            return 0
        if ratio <= 0:
            return values[0]
        if ratio >= 1:
            return values[-1]
        idx = int((len(values) - 1) * ratio)
        return values[idx]

