from __future__ import annotations

from typing import Any

from calculators import compute_pricing, explain_pricing
from domain_models import order_draft_from_payload
from event_bus import EventBus
from metrics import Metrics
from repository import OrderRepository
from utils import add_trace, ensure_trace, normalize_discount_code
from validators import validate_discount_code


class PricingService:
    def calculate(self, payload: dict[str, Any]) -> dict[str, int]:
        items = payload.get("items", [])
        currency = str(payload.get("currency", "USD")).strip().upper()
        discount = normalize_discount_code(str(payload.get("discount_code", "")))
        return compute_pricing(items, currency, discount)


class OrderFactory:
    def create(self, payload: dict[str, Any], pricing: dict[str, int]) -> dict[str, Any]:
        return {
            "order_id": str(payload.get("order_id", "")).strip(),
            "user_id": str(payload.get("user_id", "")).strip(),
            "currency": str(payload.get("currency", "USD")).strip().upper(),
            "status": "processed",
            "subtotal_cents": pricing["subtotal_cents"],
            "discount_cents": pricing["discount_cents"],
            "tax_cents": pricing["tax_cents"],
            "total_cents": pricing["total_cents"],
            "discount_code": normalize_discount_code(str(payload.get("discount_code", ""))),
        }


class OOPPipeline:
    def __init__(
        self,
        *,
        repository: OrderRepository,
        events: EventBus,
        metrics: Metrics,
        pricing: PricingService | None = None,
        factory: OrderFactory | None = None,
    ) -> None:
        self._repository = repository
        self._events = events
        self._metrics = metrics
        self._pricing = pricing or PricingService()
        self._factory = factory or OrderFactory()

    def process(self, payload: dict[str, Any], trace: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        trace_items = ensure_trace(trace)
        try:
            draft = order_draft_from_payload(payload)
        except Exception as exc:
            self._metrics.incr("invalid_payload")
            trace_items = add_trace(trace_items, "parse", {"ok": False, "reason": str(exc)})
            return {"ok": False, "reason": f"invalid_payload:{exc}", "trace": trace_items, "order": {}}

        discount_code = normalize_discount_code(str(payload.get("discount_code", "")))
        discount_ok, discount_reason = validate_discount_code(discount_code)
        if not discount_ok:
            self._metrics.incr("invalid_discount")
            trace_items = add_trace(trace_items, "discount", {"ok": False, "reason": discount_reason})
            return {"ok": False, "reason": discount_reason, "trace": trace_items, "order": {}}

        pricing = self._pricing.calculate(payload)
        trace_items = add_trace(trace_items, "pricing", {"summary": explain_pricing(pricing)})
        order = self._factory.create(payload, pricing)
        self._repository.save(order)
        self._events.emit("order_saved", {"order_id": order["order_id"]})
        self._metrics.incr("order_saved")
        trace_items = add_trace(trace_items, "save", {"ok": True})

        return {"ok": True, "reason": "processed", "trace": trace_items, "order": order}

    def process_batch(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            result = self.process(payload, trace=[])
            results.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}

    def diagnostics(self) -> dict[str, Any]:
        return {
            "metrics": self._metrics.snapshot(),
            "events": self._events.summary(),
            "stored_orders": self._repository.count(),
        }

    def process_with_tags(self, payload: dict[str, Any], extra_tags: list[str]) -> dict[str, Any]:
        item = dict(payload)
        existing = [str(tag).strip() for tag in item.get("tags", []) if str(tag).strip()]
        item["tags"] = existing + [str(tag).strip() for tag in extra_tags if str(tag).strip()]
        return self.process(item, trace=[])

    def process_many(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        results = self.process_batch(payloads)
        totals = self.collect_totals(results.get("results", []))
        return {"results": results, "totals": totals}

    def collect_totals(self, results: list[dict[str, Any]]) -> dict[str, int]:
        subtotal = 0
        total = 0
        for item in results:
            order = item.get("order", {})
            subtotal += int(order.get("subtotal_cents", 0))
            total += int(order.get("total_cents", 0))
        return {"subtotal_cents": subtotal, "total_cents": total}

    def replay(self, payload: dict[str, Any], times: int = 1) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for _ in range(max(0, int(times))):
            out.append(self.process(dict(payload), trace=[]))
        return out

