from threading import Lock
from typing import Any


class OrderRepository:
    def __init__(self) -> None:
        self._lock = Lock()
        self._orders: dict[str, dict[str, Any]] = {}

    def save(self, order: dict[str, Any]) -> None:
        order_id = str(order.get("order_id", "")).strip()
        if not order_id:
            raise ValueError("order_id required")
        with self._lock:
            self._orders[order_id] = dict(order)

    def get(self, order_id: str) -> dict[str, Any] | None:
        key = order_id.strip()
        if not key:
            return None
        with self._lock:
            item = self._orders.get(key)
            return dict(item) if item is not None else None

    def count(self) -> int:
        with self._lock:
            return len(self._orders)

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._orders.keys())

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {key: dict(value) for key, value in self._orders.items()}

    def clear(self) -> None:
        with self._lock:
            self._orders.clear()

    def remove(self, order_id: str) -> bool:
        key = order_id.strip()
        if not key:
            return False
        with self._lock:
            if key in self._orders:
                del self._orders[key]
                return True
            return False

    def has(self, order_id: str) -> bool:
        return self.get(order_id) is not None

    def values(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(value) for value in self._orders.values()]

    def total_revenue_cents(self) -> int:
        total = 0
        for order in self.values():
            total += int(order.get("total_cents", 0))
        return total

