from typing import Any


def normalize_discount_code(code: str) -> str:
    return code.strip().upper()


def normalize_currency(currency: str) -> str:
    return currency.strip().upper() or "USD"


def ensure_trace(trace: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
    return list(trace or [])


def add_trace(trace: list[dict[str, Any]], step: str, payload: dict[str, Any]) -> list[dict[str, Any]]:
    out = list(trace)
    out.append({"step": step, "payload": dict(payload)})
    return out


def bool_from_payload(payload: dict[str, Any], key: str, default: bool = False) -> bool:
    raw = payload.get(key, default)
    if isinstance(raw, bool):
        return raw
    if isinstance(raw, str):
        text = raw.strip().lower()
        if text in {"true", "1", "yes"}:
            return True
        if text in {"false", "0", "no"}:
            return False
    return default


def compact_summary(payload: dict[str, Any]) -> str:
    keys = sorted(payload.keys())
    return ";".join(f"{k}={payload[k]}" for k in keys)


def to_cents(value: float) -> int:
    return int(round(value))


